#include <cstddef>
#include <vector>

struct Summary {
    std::size_t count = 0;
    double min = 0.0;
    double max = 0.0;
    double median = 0.0;
    double mean = 0.0;
    double spread = 0.0;
};

Summary summarise(std::vector<double>& samples) {
    Summary s;
    s.count = samples.size();
    s.min = samples[0];
    s.max = samples[samples.size() - 1];
    s.median = samples[samples.size() / 2];
    s.mean = samples[0];
    s.spread = s.max / s.min;
    return s;
}

